const authHeader = req.headers.get("Authorization") ?? "";
const userClient = createClient(SUPABASE_URL, SUPABASE_ANON_KEY, {
  global: { headers: { Authorization: authHeader } },
});
const { data: { user }, error } = await userClient.auth.getUser();
if (error || !user) return new Response("Unauthorized", { status: 401 });

// Only now use the service_role client, and scope every query to user.id

drop policy if exists "Public read" on public.profiles;

create policy "Owners read their profile" on public.profiles
  for select to authenticated
  using ((select auth.uid()) = user_id);

alter table public.orders enable row level security;

create policy "Owners read their orders" on public.orders
  for select to authenticated
  using ((select auth.uid()) = user_id);

-- Keep only the owner policy for this operation
drop policy if exists "Enable read access for all users" on public.comments;

-- A policy that should narrow access, not widen it:
create policy "Only published" on public.comments
  as restrictive for select to authenticated
  using (published);

revoke execute on function public.admin_stats() from anon, public;
grant execute on function public.admin_stats() to authenticated;

-- Inside the function body:
--   if (select auth.uid()) is null then raise exception 'not allowed'; end if;
alter function public.admin_stats() set search_path = '';

const { data: { user } } = await supabase.auth.getUser();
if (!user) return new Response("Unauthorized", { status: 401 });
if (!(await withinDailyLimit(user.id))) return new Response("Too many requests", { status: 429 });

const completion = await openai.chat.completions.create({
  model,
  max_tokens: 500,
  messages: [
    { role: "system", content: SYSTEM_PROMPT },
    { role: "user", content: input.slice(0, 2000) },
